const fs = require('fs');
let javascriptMD = `
<table style="width:100%">
  <tr>
    <th>Snippets</th>
    <th>Prefix</th> 
    <th>Description</th>
  </tr>
`;
Object.keys(javascript).map((item) => {
    // 生成 md
    javascriptMD += `<tr><td>${javascript[item].body}</td><td>${javascript[item].prefix}</td><td>${javascript[item].description}</td></tr>\n`;
})
fs.writeFileSync('./javascript.html', javascriptMD + `</table>`);
